                { "apartment.item.boxingGloves", new[] { "拳击手套", "Boxing Gloves", "ボクシンググローブ" } },
                { "apartment.kitchen.stoveKnife", new[] { "灶台上有一把菜刀。\n也许能用来撬开生锈的铰链。", "There's a kitchen knife on the stove.\nMaybe I can use it to pry open the rusty hinges.", "コンロの上に包丁がある。\n錆びた蝶番をこじ開けるのに使えるかもしれない。" } },
                { "apartment.kitchen.foodCabinet.intro.1", new[] { "话说这房东也真是个狠人。\n欠他三个月的租金，不停水，不停电……", "You know, our landlord really is ruthless.\nWe owe him three months' rent, and he doesn't cut off the water or electricity...", "それにしても、あの大家も本当に容赦ないよな。\n家賃を三か月滞納しても、水も電気も止めずに……" } },
                { "apartment.kitchen.foodCabinet.intro.2", new[] { "居然把食品柜上了把锁！", "He puts a lock on the food cabinet instead!", "食品棚に鍵をかけやがった！" } },
                { "apartment.kitchen.foodCabinet.intro.3", new[] { "还是密码锁！", "A combination lock, no less!", "しかもダイヤル錠だぞ！" } },
                { "apartment.kitchen.foodCabinet.intro.4", new[] { "这种情况不报警吗？", "Shouldn't we call the police about this?", "こういうときは警察に通報しないのか？" } },
                { "apartment.kitchen.foodCabinet.intro.5", new[] { "万一警察见到你直接呼叫恶魔猎人了呢？", "What if the police see you and call the demon hunters straight away?", "警察が兄ちゃんを見て、いきなり悪魔狩りを呼んだらどうするんだ？" } },
                { "apartment.kitchen.foodCabinet.open.1", new[] { "终于是把这食品柜打开了……", "I finally got the food cabinet open...", "やっと食品棚を開けられた……" } },
                { "apartment.kitchen.foodCabinet.open.2", new[] { "这袋肉干似乎是拿来吸引恶魔的不二之选，\n毕竟它们大部分都吃肉吧……", "This bag of dried meat seems like the perfect thing for luring demons.\nMost of them eat meat, after all...", "この干し肉なら、悪魔をおびき寄せるのにうってつけだろう。\n悪魔の大半は肉を食べるはずだから……" } },
                { "apartment.kitchen.foodCabinet.repeat", new[] { "我没必要带更多了。", "I don't need to take any more.", "これ以上持っていく必要はない。" } },
                { "apartment.ui.foodCabinet.title", new[] { "食品柜密码锁", "Food Cabinet Combination Lock", "食品棚のダイヤル錠" } },
                { "apartment.ui.foodCabinet.hint", new[] { "A / D 选择密码位　　W / S 调整数值\nQ 退出", "A / D: Select Digit　　W / S: Change Value\nQ: Exit", "A / D：桁を選択　　W / S：数字を変更\nQ：終了" } },
                { "apartment.bathroom.medicineCabinet.intro.1", new[] { "药柜被锁住了……", "The medicine cabinet is locked...", "薬棚に鍵がかかっている……" } },
                { "apartment.bathroom.medicineCabinet.intro.2", new[] { "看来还是房东干的，我每天都要从里面拿膏药出来贴在脸上，不可能把它锁住的。", "Looks like the landlord did this too. I take a plaster from here every day to cover my face, so I would never lock it.", "これも大家の仕業らしい。僕は毎日ここから膏薬を出して顔に貼るんだから、自分で鍵をかけるはずがない。" } },
                { "apartment.bathroom.medicineCabinet.intro.3", new[] { "话说回来……钥匙去哪里了？", "Come to think of it... where did the key go?", "そういえば……鍵はどこへ行ったんだ？" } },
                { "apartment.bathroom.medicineCabinet.repeat", new[] { "现在的当务之急是找到药柜的钥匙。", "The first thing I need to do is find the medicine cabinet key.", "今はまず、薬棚の鍵を見つけないと。" } },
                { "apartment.ui.medicineCabinet.title", new[] { "药柜", "Medicine Cabinet", "薬棚" } },
                { "apartment.ui.medicineCabinet.hint", new[] { "E 选中药品　　WASD 与相邻药品交换　　归位的药品无法移动", "E: Select Medicine　　WASD: Swap with an Adjacent Medicine　　Correctly Placed Medicines Cannot Be Moved", "E：薬を選択　　WASD：隣の薬と交換　　正しい位置の薬は移動不可" } },
                { "apartment.bathroom.toilet.intro.1", new[] { "也许我该往这里面看看……说不准会发现什么。", "Maybe I should take a look inside... I might find something.", "中を見てみたほうがいいかもしれない……何か見つかるかも。" } },
                { "apartment.bathroom.toilet.intro.2", new[] { "该怎么做呢？", "How should I go about it?", "どうすればいい？" } },
                { "apartment.bathroom.toilet.intro.3", new[] { "例如说……冲马桶？", "Maybe... flush the toilet?", "例えば……水を流してみるとか？" } },
                { "apartment.bathroom.toilet.second.1", new[] { "哥，你在冲马桶吗？", "Bro, are you flushing the toilet?", "兄ちゃん、トイレの水を流してるのか？" } },
                { "apartment.bathroom.toilet.second.2", new[] { "省着点用水，我可不想再打几次黑拳挣水费！", "Go easy on the water. I don't want to fight a few more underground matches just to pay the water bill!", "水は節約してくれよ。水道代のために、また何試合も闇試合をするのはごめんだからな！" } },
                { "apartment.bathroom.toilet.third", new[] { "你怕不是又把浴盐球掉进去了？", "Don't tell me you dropped another bath bomb in there?", "またバスボムを落としたんじゃないだろうな？" } },
                { "apartment.bathroom.toilet.fourth.1", new[] { "……这房东果真是个狠人。", "...That landlord really is ruthless.", "……あの大家、本当に容赦がないな。" } },
                { "apartment.bathroom.toilet.fourth.2", new[] { "而且也是个坏人。拿准了我因为脸上这道痕迹而不敢报警的把柄。", "And a cruel man, too. He knows I won't dare call the police because of this mark on my face, and he's using that against me.", "それに悪人でもある。僕が顔のこの痕のせいで警察に通報できないと見抜いて、そこにつけ込んでいる。" } },
                { "apartment.bathroom.vent.observe", new[] { "从这里看去，下水道里贴着一张纸像是写着什么数字，也许和密码锁有关。", "From here, I can see a piece of paper stuck inside the sewer. It looks like there's some kind of number written on it—maybe it has something to do with the combination lock.", "ここから見ると、下水道の中に紙が貼りついていて、何か数字が書かれているようだ。ダイヤル錠と関係があるのかもしれない。" } },
                { "apartment.bathroom.vent.default", new[] { "但我够不到它，最好找个长一点的东西把它勾过来。", "But I can't reach it. I should find something long enough to hook it over here.", "でも手が届かない。何か長い物で引っかけて、こっちへ寄せたほうがよさそうだ。" } },
                { "apartment.bathroom.vent.knife.1", new[] { "但我够不到它，这把刀够长，可是很可能会把那张纸弄掉。", "But I can't reach it. This knife is long enough, but I'd probably just knock the paper down.", "でも手が届かない。この包丁なら長さは足りるが、紙を落としてしまいそうだ。" } },
                { "apartment.bathroom.vent.knife.2", new[] { "得找点什么黏的东西涂在刀上，把纸张像粘知了一样粘下来。", "I need something sticky to put on the knife, so I can catch the paper the way you'd catch a cicada with a sticky pole.", "包丁に何か粘る物をつけて、粘着竿でセミを捕るみたいに紙をくっつけて取らないと。" } },
                { "apartment.bathroom.vent.stickyKnife", new[] { "现在有了这粘竿菜刀，我就能把它粘过来了。", "Now that I have this sticky-pole knife, I can stick the paper to it and pull it over here.", "この粘着竿包丁があれば、紙をくっつけてこっちへ引き寄せられる。" } },
                { "apartment.bathroom.passwordNote.1", new[] { "虽然一大半都被胶糊住了，但我还是看得出来……是一张上面写着数字8的纸条。", "Most of it is smeared with glue, but I can still make it out... It's a note with the number 8 written on it.", "半分以上が糊でべたべたになっているが、それでも分かる……数字の「8」が書かれた紙だ。" } },
                { "apartment.bathroom.passwordNote.2", new[] { "或许与密码锁有关。", "It might have something to do with the combination lock.", "ダイヤル錠と関係があるのかもしれない。" } },
                { "apartment.crafting.stickyKnife", new[] { "兴许我能把这平时拿来遮挡的膏药贴在钝刀上，做成一个特别奇怪的粘竿。", "Maybe I can stick this plaster—the one I usually use to cover my face—onto the blunt knife and make a very strange kind of sticky pole.", "いつも顔を隠すのに使っているこの膏薬を、なまくらな包丁に貼りつければ、かなり妙な粘着竿を作れるかもしれない。" } },
                { "apartment.item.knife", new[] { "菜刀", "Kitchen Knife", "包丁" } },
                { "apartment.item.driedMeat", new[] { "肉干", "Dried Meat", "干し肉" } },
                { "apartment.item.medicineCabinetKey", new[] { "药柜钥匙", "Medicine Cabinet Key", "薬棚の鍵" } },
                { "apartment.item.plaster", new[] { "膏药", "Plaster", "膏薬" } },
                { "apartment.item.stickyKnife", new[] { "粘竿菜刀", "Sticky-Pole Knife", "粘着竿包丁" } },
                { "apartment.chunbaoBedroom.door.boundary", new[] { "喂喂，做人可得讲点界限！", "Hey, hey! You've got to respect people's boundaries!", "おいおい、人として一線は守れよ！" } },
                { "apartment.chunbaoBedroom.door.clueQuestion", new[] { "万一里边有密码锁相关的线索呢？", "What if there's a clue to the combination lock in there?", "もし中にダイヤル錠の手掛かりがあったら？" } },
                { "apartment.chunbaoBedroom.door.beforeSandbag", new[] { "那是我的房间！要找线索也要我自己进去找。", "That's my room! If there are clues to find, I'll go in and look for them myself.", "俺の部屋だぞ！　手掛かりを探すにしても、俺が自分で入って探す。" } },
                { "apartment.chunbaoBedroom.door.afterSandbag.1", new[] { "那是我的房间！要找线索……", "That's my room! If you want to look for clues...", "俺の部屋だぞ！　手掛かりを探したいなら……" } },
                { "apartment.chunbaoBedroom.door.afterSandbag.2", new[] { "至少得帮我修好这个沙袋才让你进去。", "At least fix this sandbag for me before I let you in.", "せめてこのサンドバッグを直してからじゃないと、入れてやらない。" } },
                { "apartment.chunbaoBedroom.desk.1", new[] { "上面放着春宝小时候最喜欢的玩具，红熊可米。", "On it is Chunbao's favorite childhood toy, Red Bear Comy.", "上には、春宝が子供の頃に一番気に入っていたおもちゃ、「赤いクマのコミー」が置いてある。" } },
                { "apartment.chunbaoBedroom.desk.2", new[] { "是十来年前一个一段时间内人气火爆迅速就绝版了的潮流玩偶。", "It was a trendy doll that became wildly popular for a brief time about ten years ago, then quickly went out of production.", "十年ほど前、一時期爆発的な人気を集めたものの、すぐに生産終了になった流行の人形だ。" } },
                { "apartment.chunbaoBedroom.desk.3", new[] { "……", "...", "……" } },
                { "apartment.chunbaoBedroom.desk.4", new[] { "也是爸爸妈妈在我六岁时那次意外前留给她的唯一纪念品……", "It's also the only keepsake our parents left her before the accident when I was six...", "そして、僕が六歳のときのあの事故より前に、父さんと母さんが彼女に残した唯一の形見でもある……" } },
                { "apartment.chunbaoBedroom.desk.5", new[] { "嗯，她的作业都写完收好了。", "Hmm. She's finished all her homework and put it away properly.", "うん。宿題は全部終わらせて、きちんと片づけてある。" } },
                { "apartment.chunbaoBedroom.wardrobe.1", new[] { "衣柜里都是些朴素耐脏的平时衣物和校服。", "The wardrobe contains nothing but plain, practical everyday clothes and school uniforms.", "クローゼットにあるのは、地味で汚れの目立たない普段着と制服ばかりだ。" } },
                { "apartment.chunbaoBedroom.wardrobe.2", new[] { "毕竟我们没有条件置办些更好的衣服，更别提给春宝买什么化妆品了……", "We can't afford nicer clothes, after all—let alone any makeup for Chunbao...", "僕たちにはもっといい服を買う余裕なんてない。春宝に化粧品を買ってやるなんて、なおさらだ……" } },
                { "apartment.chunbaoBedroom.wardrobe.3", new[] { "我在说些什么……她根本不在意这些。", "What am I talking about...? She doesn't care about any of that.", "何を言っているんだ、僕は……彼女はそんなこと、まるで気にしていない。" } },
                { "apartment.chunbaoBedroom.bed.first.1", new[] { "春宝的厨艺很好，但一直不怎么勤做家务，床铺一直很乱。", "Chunbao is a great cook, but she's never been very diligent about housework. Her bed is always a mess.", "春宝は料理上手だけど、家事には昔からあまりまめじゃない。ベッドはいつも散らかっている。" } },
                { "apartment.chunbaoBedroom.bed.first.2", new[] { "每天的学业已经很繁重了，有时候还要去打黑拳赚钱，她怎么可能有时间呢？", "Her schoolwork is demanding enough already, and sometimes she has to earn money in underground fights. How could she possibly have the time?", "毎日の勉強だけでも大変なのに、ときには闇試合で金まで稼がなければならない。時間なんてあるはずがない。" } },
                { "apartment.chunbaoBedroom.bed.first.3", new[] { "等等，这是……", "Wait, is this...?", "待て、これは……" } },
                { "apartment.chunbaoBedroom.bed.first.4", new[] { "是春宝的手机，还开着，上面在运行一款游戏。", "It's Chunbao's phone. It's still on, with a game running on it.", "春宝のスマホだ。電源が入ったままで、ゲームが起動している。" } },
                { "apartment.chunbaoBedroom.bed.first.5", new[] { "看来跟往常一样，她想不靠任何人的帮助将游戏破关。", "Just like always, it looks like she's trying to beat the game without anyone's help.", "いつものように、誰の助けも借りずにクリアしようとしているらしい。" } },
                { "apartment.chunbaoBedroom.bed.first.6", new[] { "她一直这么要强。", "She's always been so determined to do everything herself.", "彼女は昔から、何でも自分でやり遂げようとする。" } },
                { "apartment.chunbaoBedroom.bed.first.7", new[] { "这次就由我来吧，就当是给她一个惊喜……", "This time, I'll do it. I can make it a surprise for her...", "今回は僕がやろう。彼女へのちょっとしたサプライズということで……" } },
                { "apartment.chunbaoBedroom.bed.repeat", new[] { "还是别把这本来就乱的床铺弄得更乱的好。", "I probably shouldn't make this already messy bed even messier.", "ただでさえ散らかっているベッドを、これ以上乱さないほうがいい。" } },
                { "apartment.chunbaoBedroom.phone.start", new[] { "那么，就由我来通关这个游戏吧……", "All right, then. I'll be the one to beat this game...", "それなら、このゲームは僕がクリアしよう……" } },
                { "apartment.chunbaoBedroom.phone.password.first.1", new[] { "这屏幕……怎么回事？", "What's going on with this screen...?", "この画面……どうなっているんだ？" } },
                { "apartment.chunbaoBedroom.phone.password.first.2", new[] { "上面竟显示出一个数字1，难道是坏了？", "It's displaying the number 1. Is it broken?", "数字の「1」が表示されている。壊れたのか？" } },
                { "apartment.chunbaoBedroom.phone.password.first.3", new[] { "还是……和密码锁有关？", "Or... does it have something to do with the combination lock?", "それとも……ダイヤル錠と関係があるのか？" } },
                { "apartment.chunbaoBedroom.phone.password.repeat", new[] { "上面有一个数字1，可能同密码锁有关。", "There's a number 1 on it. It may have something to do with the combination lock.", "数字の「1」が表示されている。ダイヤル錠と関係があるのかもしれない。" } },
                { "apartment.ui.phoneGame.title", new[] { "林春宝的手机游戏", "Lin Chunbao's Phone Game", "林春宝のスマホゲーム" } },
                { "apartment.ui.phoneGame.hint", new[] { "按 W / S 控制钥匙上下移动，避开障碍并抵达门前", "Press W / S to Move the Key Up and Down. Avoid the Obstacles and Reach the Door.", "W / Sで鍵を上下に動かし、障害物を避けて扉までたどり着け" } },
                { "apartment.protagonistBedroom.bed.1", new[] { "我房间的陈设比春宝简单得多。毕竟照顾好她是我的责任。\n平时写作业我也会在餐桌上写。", "My room is much more sparsely furnished than Chunbao's. Looking after her is my responsibility, after all.\nI usually do my homework at the dining table too.", "僕の部屋は春宝の部屋よりずっと簡素だ。彼女をきちんと支えるのは僕の責任だから。\n普段、宿題も食卓でやっている。" } },
                { "apartment.protagonistBedroom.bed.2", new[] { "而且简单的房间整理起来也很方便。", "Besides, a simple room is easy to keep tidy.", "それに、物の少ない部屋は片づけるのも楽だ。" } },
                { "apartment.protagonistBedroom.plasterBoxes.1", new[] { "这些是我一直以来用来掩盖脸上这痕迹的膏药剩下的包装。", "These are the empty packages from the plasters I've always used to cover the mark on my face.", "これは、ずっと顔のこの痕を隠すために使ってきた膏薬の空き箱だ。" } },
                { "apartment.protagonistBedroom.plasterBoxes.2", new[] { "……", "...", "……" } },
                { "apartment.protagonistBedroom.plasterBoxes.3", new[] { "……人们不接纳我，因为我是一半的恶魔。", "...People don't accept me because I'm half demon.", "……人々は僕を受け入れない。僕が半分、悪魔だから。" } },
                { "apartment.protagonistBedroom.plasterBoxes.4", new[] { "恶魔会因为我是一半的人类而和人一样不接纳我吗？", "Would demons reject me just as humans do because I'm half human?", "悪魔も、僕が半分人間だからという理由で、人間と同じように僕を受け入れないのだろうか？" } },
                { "apartment.protagonistBedroom.plasterBoxes.5", new[] { "所以有没有人能告诉我我到底是什么！", "Then can somebody tell me what I am?!", "だったら誰か、僕がいったい何なのか教えてくれ！" } },
                { "apartment.protagonistBedroom.bedside.locked.1", new[] { "这是我的床头柜，衣服什么的都放在里面。", "This is my nightstand. I keep my clothes and other things in it.", "これは僕のベッド脇の棚だ。服なんかを中にしまっている。" } },
                { "apartment.protagonistBedroom.bedside.locked.2", new[] { "但是现在锁住了，钥匙我从昨天就一直在找。", "But it's locked now. I've been looking for the key since yesterday.", "でも今は鍵がかかっている。昨日からずっと鍵を探しているんだ。" } },
                { "apartment.protagonistBedroom.bedside.hasKey.1", new[] { "这是我的床头柜，衣服什么的都放在里面。", "This is my nightstand. I keep my clothes and other things in it.", "これは僕のベッド脇の棚だ。服なんかを中にしまっている。" } },
                { "apartment.protagonistBedroom.bedside.hasKey.2", new[] { "现在找到了钥匙，终于可以打开它了。", "Now that I've found the key, I can finally open it.", "鍵が見つかったから、ようやく開けられる。" } },
                { "apartment.protagonistBedroom.bedside.open.1", new[] { "……除了衣服外，床头柜里有一张上面写着数字7的纸条。", "...Besides the clothes, there's a note in the nightstand with the number 7 written on it.", "……服のほかに、ベッド脇の棚には数字の「7」が書かれた紙が入っている。" } },
                { "apartment.protagonistBedroom.bedside.open.2", new[] { "或许与密码锁有关。", "It might have something to do with the combination lock.", "ダイヤル錠と関係があるのかもしれない。" } },
                { "apartment.protagonistBedroom.passwordNote.1", new[] { "……是一张上面写着数字6的纸条。", "...It's a note with the number 6 written on it.", "……数字の「6」が書かれた紙だ。" } },
                { "apartment.protagonistBedroom.passwordNote.2", new[] { "或许与密码锁有关。", "It might have something to do with the combination lock.", "ダイヤル錠と関係があるのかもしれない。" } },
                { "apartment.item.bedsideKey", new[] { "床头柜钥匙", "Nightstand Key", "ベッド脇の棚の鍵" } },
                { "apartment.departure.ready", new[] { "你准备好了？", "Are you ready?", "準備はできたか？" } },
                { "apartment.departure.askLocation", new[] { "我什么都拿好了，告诉我那个新开的小归墟在哪里吧。", "I've got everything. Tell me where that newly opened small hole of Abyss is.", "必要なものは全部持った。新しく開いた小さな深淵の穴がどこにあるのか、教えてくれ。" } },
                { "apartment.departure.directions", new[] { "就在郊区。出了公寓楼你向右转，\n从公交车站的方向看来就是向左转。", "It's in the suburbs. Turn right when you leave the apartment building.\nLooking from the bus stop, that would be a left.", "郊外だ。アパートを出たら右に曲がれ。\nバス停のほうから見れば左だ。" } },
                { "apartment.departure.understood", new[] { "明白了。", "Understood.", "分かった。" } },
                { "apartment.departure.warningLead", new[] { "还有一件事……", "One more thing...", "もう一つ……" } },
                { "apartment.departure.prompt", new[] { "嗯？", "Hmm?", "うん？" } },
                { "apartment.departure.gangWarning", new[] { "那里绝对有丧家犬的人，就是我们市里\n那个臭名昭著的猎魔帮派。", "There'll definitely be Stray Dogs there—you know, that notorious\ndemon-hunting gang in our city.", "あそこには絶対「負け犬」の連中がいる。うちの街で悪名高い、\nあの悪魔狩りギャングだ。" } },
                { "apartment.departure.contactPromise", new[] { "明白了，真出了什么事我会联系你的。", "Understood. If anything happens, I'll contact you.", "分かった。何かあったら連絡する。" } },
                { "apartment.confrontation.initial.linChallenge", new[] { "……凭什么？就凭一张没盖章的破纸？\n我哥脸上那点东西怎么了？碍着谁了？！", "...On what grounds? Because of one lousy piece of paper without so much as a stamp?\nWhat's wrong with that mark on my brother's face? Who's it hurting?!", "……何の権利があって？　判も押してないこんな紙切れ一枚で？\n兄貴の顔のあれが何だってんだ？　誰に迷惑かけたよ！？" } },
                { "apartment.confrontation.initial.officialNotice", new[] { "林春宝同学，请冷静。这是学校的决定，也是为了全体师生的安全考虑。\n您兄长面部的异常情况，根据《非人知性体接触者管理暂行条例》第七款，需要接受指定机构的隔离检查。\n在检查结果出来前，暂停其一切校内活动。", "Miss Lin Chunbao, please remain calm. This is the school's decision, made with the safety of all students and faculty in mind.\nUnder Article 7 of the Interim Regulations on the Management of Persons in Contact with Non-Human Sapient Entities, the abnormality on your brother's face requires an isolation examination at a designated facility.\nAll of his on-campus activities are suspended pending the results.", "林春宝さん、落ち着いてください。これは学校の決定であり、全学生および教職員の安全を考慮したものです。\nお兄様の顔面に見られる異常については、『非人間知性体接触者管理暫定条例』第七条に基づき、指定機関での隔離検査を受けていただく必要があります。\n検査結果が出るまで、学内での一切の活動を停止します。" } },
                { "apartment.confrontation.initial.linAccusation", new[] { "不是房东就是哪个混蛋搞的鬼！", "It was either the landlord or some other bastard who set this up!", "大家か、どこかのクソ野郎が仕組んだに決まってる！" } },
                { "apartment.confrontation.notice.report", new[] { "屋主回来了。通知您已经看到。请于四十八小时内，携带这份通知，\n前往市立第三检疫中心报到。逾期未到，将由安全部门强制执行。", "The resident is back. You have seen the notice. Please take it with you and report\nto Municipal Quarantine Center No. 3 within forty-eight hours. Failure to do so by the deadline will result in compulsory action by the Security Department.", "住人が戻りましたね。通知はご覧いただいたとおりです。この通知を持参のうえ、四十八時間以内に\n市立第三検疫センターへ出頭してください。期限までに出頭しない場合は、安全部門が強制執行します。" } },
                { "apartment.confrontation.notice.silence", new[] { "……", "...", "……" } },
                { "apartment.confrontation.notice.acknowledge", new[] { "我知道了。", "I understand.", "分かりました。" } },
                { "apartment.confrontation.threat.lead", new[] { "你知道吗……", "You know...", "知っていますか……" } },
                { "apartment.confrontation.threat.cleanup", new[] { "如果我们俩是清理部门的人，会考虑当场把你和你妹妹的人头\n抛到大街上。", "If the two of us were from the Cleanup Department, we'd consider cutting off your and your sister's heads right here\nand tossing them into the street.", "私たち二人が処理部門の者だったなら、あなたと妹さんの首をその場ではねて、\n大通りに放り出すことも考えたでしょう。" } },
                { "apartment.confrontation.threat.leave", new[] { "走。", "Let's go.", "行きましょう。" } },
                { "apartment.confrontation.final.linPlea", new[] { "哥！你不能去！那种地方进去谁知道会怎样！\n我们走，现在就收拾东西……", "Bro! You can't go! Who knows what they'll do to you in a place like that?\nLet's leave. We'll pack our things right now...", "兄貴！　行っちゃ駄目だ！　あんな所に入ったら何をされるか分からない！\nここを出よう。今すぐ荷物をまとめて……" } },
                { "apartment.confrontation.final.evictionOrder", new[] { "这停学通知措辞严谨，引用条例，看似合法合规。\n但它本质上是一纸驱逐令。", "This suspension notice is carefully worded and cites the regulations. On the surface, it appears perfectly lawful.\nBut in essence, it's an eviction order.", "この停学通知は用語も厳密で、条例まで引用している。一見すると、法に則った正当なものだ。\nだが本質的には、ただの追放命令だ。" } },
                { "apartment.confrontation.final.noPlace", new[] { "看来，这里真的没有我的位置了。", "It seems there really is no place for me here.", "どうやら、ここには本当に僕の居場所がないらしい。" } },
                { "apartment.confrontation.final.leaveTogether", new[] { "所以，我们得去别处看看。", "So we'll have to look somewhere else.", "だから、僕たちは別の場所を探さなければならない。" } },
                { "apartment.ending.noBelonging.title", new[] { "结局：无归属者", "Ending: Nowhere to Belong", "結末：居場所なき者" } },
                { "apartment.ending.noBelonging.1", new[] { "窗外的城市在夜雨中灯火阑珊，远处，郊区方向的夜空似乎比别处更暗沉一些。", "Beyond the window, the city's lights glow faintly through the rainy night. In the distance, the sky over the suburbs seems darker than anywhere else.", "窓の外では、夜の雨に濡れた街の灯がかすかに瞬いている。遠く、郊外の方角の夜空は、ほかの場所よりも暗く沈んで見える。" } },
                { "apartment.ending.noBelonging.2", new[] { "那里有归墟，也有你的归属。", "There lies the Abyss—and a place where you belong.", "そこには深淵があり、あなたの居場所もある。" } },
                { "apartment.ending.noBelonging.3", new[] { "那里有被掩盖的真相，和正在发生的、无人听见的对话。", "There are truths concealed there, and conversations taking place that no one else can hear.", "そこには覆い隠された真実と、誰にも聞かれることなく交わされている対話がある。" } },
                { "apartment.ending.noBelonging.4", new[] { "你将通知慢慢折起，塞进口袋，和那块温热的晶石放在一起。", "You slowly fold the notice and slip it into your pocket, placing it beside the warm crystal.", "あなたは通知をゆっくりと折りたたみ、あの温かな晶石と一緒にポケットへしまう。" } },
                { "apartment.ending.noBelonging.5", new[] { "这是真正属于你的结局。", "This is the ending that truly belongs to you.", "これこそが、本当にあなた自身の結末だ。" } },
                { "apartment.ending.thanks", new[] { "感谢游玩", "Thank You for Playing", "プレイしていただき、ありがとうございました" } }
